import { loadFont as loadPlayfair } from "@remotion/google-fonts/PlayfairDisplay";
import { loadFont as loadVibes } from "@remotion/google-fonts/GreatVibes";
import { loadFont as loadPoppins } from "@remotion/google-fonts/Poppins";
import { AbsoluteFill, Easing, Img, interpolate, staticFile, useCurrentFrame } from "remotion";

// BinaGlow (loja de autocuidado no ABC): vitrine vertical 1080×1920, 30 fps, tom doce e chamativo para mulheres.
// Identidade do Instagram e das artes: rosa pink, blush, vinho; BINA em serifa com coroa, GLOW espaçado, script à mão.
// Fotos dos produtos em tela cheia ou em cartão grande; lettering em pílula branca + faixa pink, cada palavra no instante
// em que é dita (tempos da locução em public/binaglow/voz-v1.mp3). Sem áudio aqui: mixagem em tools/make_audio_binaglow.py.

const { fontFamily: SERIF } = loadPlayfair("normal", { weights: ["600", "700"], subsets: ["latin", "latin-ext"] });
loadPlayfair("italic", { weights: ["700"], subsets: ["latin", "latin-ext"] });
const { fontFamily: SCRIPT } = loadVibes("normal", { weights: ["400"], subsets: ["latin", "latin-ext"] });
const { fontFamily: SANS } = loadPoppins("normal", { weights: ["300", "500", "600", "700"], subsets: ["latin", "latin-ext"] });

export const BG_FPS = 30;
const VO = 0.15;
const VOICE = 33.12;
export const BG_FRAMES = Math.round((VO + VOICE + 1.7) * BG_FPS);
const BLUSH = "#FBE4EB";
const PINK = "#E63E7E";
const ROSE = "#F4A6C0";
const WINE = "#5B1631";
const WHITE = "#FFFFFF";

const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const IN_OUT = Easing.bezier(0.65, 0, 0.35, 1);
const BACK = Easing.bezier(0.34, 1.35, 0.64, 1);
const k = (t: number, a: number, d = 0.4, ease = OUT) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: ease });
const v = (s: number) => s + VO;

// ───────── texto: cada palavra sobe de trás de uma linha (máscara) ─────────
type W = [string, number];
const Words: React.FC<{ t: number; words: W[]; size: number; font?: string; weight?: number; italic?: boolean; color?: string; ls?: string }> = ({ t, words, size, font = SANS, weight = 600, italic, color = WINE, ls = "-0.01em" }) => (
  <div style={{ display: "flex", justifyContent: "center", gap: `${size * 0.24}px`, whiteSpace: "nowrap", fontFamily: font, fontWeight: weight, fontStyle: italic ? "italic" : "normal", fontSize: size, lineHeight: 1.18, letterSpacing: ls, color }}>
    {words.map(([w, at], i) => {
      const e = k(t, v(at) - 0.06, 0.42);
      return (
        <span key={i} style={{ display: "inline-block", overflow: "hidden", padding: font === SCRIPT ? "0.1em 0.12em 0.18em" : "0 0.04em 0.06em" }}>
          <span style={{ display: "inline-block", transform: `translateY(${(1 - e) * 110}%)` }}>{w}</span>
        </span>
      );
    })}
  </div>
);
// pílula branca com texto vinho (linha de apoio)
const Pill: React.FC<{ t: number; at: number; words: W[]; size?: number }> = ({ t, at, words, size = 52 }) => {
  const e = k(t, v(at) - 0.1, 0.45, BACK);
  return (
    <div style={{ padding: `${size * 0.2}px ${size * 0.6}px`, borderRadius: 999, background: WHITE, boxShadow: "0 10px 30px rgba(91,22,49,0.18)", transform: `scale(${0.6 + 0.4 * e})`, opacity: k(t, v(at) - 0.1, 0.12) }}>
      <Words t={t} words={words} size={size} weight={500} />
    </div>
  );
};
// faixa pink que se desenha da esquerda, com o título em serifa itálica branca
const Bar: React.FC<{ t: number; at: number; words: W[]; size?: number; color?: string }> = ({ t, at, words, size = 104, color = PINK }) => (
  <div style={{ position: "relative", padding: `${size * 0.06}px ${size * 0.36}px ${size * 0.1}px` }}>
    <div style={{ position: "absolute", inset: 0, borderRadius: size * 0.2, background: color, boxShadow: "0 14px 34px rgba(230,62,126,0.32)", transform: `scaleX(${k(t, v(at) - 0.12, 0.38, IN_OUT)})`, transformOrigin: "0 50%" }} />
    <div style={{ position: "relative" }}>
      <Words t={t} words={words} size={size} font={SERIF} weight={700} italic color={WHITE} ls="-0.015em" />
    </div>
  </div>
);
const Stack: React.FC<{ top: number; gap?: number; children: React.ReactNode }> = ({ top, gap = 18, children }) => (
  <div style={{ position: "absolute", left: 120, right: 120, top, display: "flex", flexDirection: "column", alignItems: "center", gap }}>{children}</div>
);

// ───────── imagem ─────────
// a mesma foto desfocada atrás, clareada para o blush
const Backdrop: React.FC<{ src: string; t: number; a: number }> = ({ src, t, a }) => (
  <AbsoluteFill style={{ overflow: "hidden", background: BLUSH }}>
    <Img src={staticFile(`binaglow/${src}`)} style={{ width: "100%", height: "100%", objectFit: "cover", filter: "blur(46px) saturate(1.2)", transform: `scale(${1.3 + 0.05 * k(t, a, 3, IN_OUT)})` }} />
    <AbsoluteFill style={{ background: "rgba(251,228,235,0.62)" }} />
  </AbsoluteFill>
);
// cartão grande: entra subindo com mola e segue numa aproximação lenta
const Card: React.FC<{ t: number; src: string; a: number; b: number; w: number; h: number; top: number; from?: "up" | "left" | "right" | "scale" }> = ({ t, src, a, b, w, h, top, from = "scale" }) => {
  const e = k(t, a, 0.55, BACK);
  const off = (1 - e) * 260;
  const tr = from === "scale" ? "" : from === "up" ? `translateY(${off}px)` : from === "left" ? `translateX(${-off}px)` : `translateX(${off}px)`;
  const z = interpolate(t, [a, b], [1, 1.07], cl);
  return (
    <div style={{ position: "absolute", left: (1080 - w) / 2, top, width: w, height: h, borderRadius: 36, overflow: "hidden", background: WHITE, boxShadow: "0 30px 70px rgba(91,22,49,0.28)", transform: `${tr} scale(${0.92 + 0.08 * e})`, opacity: k(t, a, 0.15) }}>
      <Img src={staticFile(`binaglow/${src}`)} style={{ width: "100%", height: "100%", objectFit: "cover", transform: `scale(${z})` }} />
    </div>
  );
};

// ───────── marca: coroa + BINA + GLOW dentro do anel do perfil ─────────
const Crown: React.FC<{ size: number; color?: string }> = ({ size, color = PINK }) => (
  <svg width={size} height={size * 0.62} viewBox="0 0 100 62">
    <path d="M8 52 L4 14 L28 34 L50 4 L72 34 L96 14 L92 52 Z" fill={color} />
    <rect x="8" y="54" width="84" height="7" rx="3.5" fill={color} />
    <circle cx="4" cy="12" r="5" fill={color} /><circle cx="50" cy="4" r="5" fill={color} /><circle cx="96" cy="12" r="5" fill={color} />
  </svg>
);
const Logo: React.FC<{ t: number; at: number; d: number; ring?: boolean }> = ({ t, at, d, ring = true }) => {
  const r = d / 2 - 10;
  const draw = k(t, at - 0.3, 0.9, IN_OUT);
  return (
    <div style={{ position: "relative", width: d, height: d }}>
      <div style={{ position: "absolute", inset: 18, borderRadius: "50%", background: WHITE, boxShadow: "0 24px 60px rgba(91,22,49,0.16)", transform: `scale(${0.7 + 0.3 * k(t, at - 0.3, 0.6, BACK)})`, opacity: k(t, at - 0.3, 0.15) }} />
      {ring ? (
        <svg width={d} height={d} style={{ position: "absolute", inset: 0, transform: `rotate(${-90 + Math.max(0, t - at) * 30}deg)` }}>
          <defs>
            <linearGradient id="bgRing" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stopColor={PINK} /><stop offset="0.55" stopColor={ROSE} /><stop offset="1" stopColor={WINE} /></linearGradient>
          </defs>
          <circle cx={d / 2} cy={d / 2} r={r} fill="none" stroke="url(#bgRing)" strokeWidth={d * 0.022} strokeLinecap="round" pathLength={1} strokeDasharray="1" strokeDashoffset={1 - draw} />
        </svg>
      ) : null}
      <div style={{ position: "absolute", inset: 0, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center" }}>
        <div style={{ transform: `translateY(${(1 - k(t, at, 0.5, BACK)) * 40}px) scale(${k(t, at, 0.5, BACK)})`, marginBottom: d * 0.01 }}>
          <Crown size={d * 0.17} />
        </div>
        <div style={{ display: "flex", fontFamily: SERIF, fontWeight: 600, fontSize: d * 0.27, lineHeight: 1, color: WINE, letterSpacing: "0.02em" }}>
          {"BINA".split("").map((c, i) => {
            const e = k(t, at + 0.04 + i * 0.05, 0.45);
            return (
              <span key={i} style={{ display: "inline-block", overflow: "hidden", paddingBottom: "0.06em" }}>
                <span style={{ display: "inline-block", transform: `translateY(${(1 - e) * 110}%)` }}>{c}</span>
              </span>
            );
          })}
        </div>
        <div style={{ fontFamily: SANS, fontWeight: 300, fontSize: d * 0.075, color: PINK, letterSpacing: `${0.55 - 0.15 * k(t, at + 0.3, 0.7)}em`, paddingLeft: "0.5em", marginTop: d * 0.012, opacity: k(t, at + 0.3, 0.3) }}>GLOW</div>
      </div>
    </div>
  );
};

// ───────── ícones de traço (desenham-se ao entrar) ─────────
const Icon: React.FC<{ t: number; at: number; kind: "jar" | "brush" | "pin"; size: number; color?: string }> = ({ t, at, kind, size, color = WHITE }) => {
  const d = k(t, at - 0.1, 0.7, IN_OUT);
  const pop = k(t, at - 0.15, 0.5, BACK);
  const s = { fill: "none", stroke: color, strokeWidth: 5, strokeLinecap: "round" as const, strokeLinejoin: "round" as const, pathLength: 1, strokeDasharray: "1", strokeDashoffset: 1 - d };
  return (
    <svg width={size} height={size} viewBox="0 0 100 100" style={{ transform: `scale(${0.5 + 0.5 * pop})`, opacity: k(t, at - 0.15, 0.1), overflow: "visible" }}>
      {kind === "jar" ? (
        <>
          <rect x="22" y="18" width="56" height="16" rx="5" {...s} />
          <path d="M18 40 Q18 34 24 34 L76 34 Q82 34 82 40 L82 80 Q82 88 74 88 L26 88 Q18 88 18 80 Z" {...s} />
          <path d="M34 56 Q50 70 66 56" {...s} />
          <path d="M70 6 L72 12 L78 14 L72 16 L70 22 L68 16 L62 14 L68 12 Z" fill={color} opacity={d} />
        </>
      ) : kind === "brush" ? (
        <>
          <ellipse cx="50" cy="32" rx="24" ry="28" {...s} />
          <path d="M42 64 L44 94 L56 94 L58 64" {...s} />
          {[[40, 20], [50, 18], [60, 20], [36, 32], [46, 32], [56, 32], [64, 32], [40, 44], [50, 46], [60, 44]].map(([x, y], i) => (
            <circle key={i} cx={x} cy={y} r={2.6} fill={color} opacity={k(t, at + 0.2 + i * 0.03, 0.2)} />
          ))}
        </>
      ) : (
        <>
          <path d="M50 92 Q20 58 20 38 A30 30 0 0 1 80 38 Q80 58 50 92 Z" {...s} />
          <circle cx="50" cy="38" r="11" {...s} />
        </>
      )}
    </svg>
  );
};
const Heart: React.FC<{ size: number; color?: string }> = ({ size, color = PINK }) => (
  <svg width={size} height={size} viewBox="0 0 24 24"><path d="M12 21s-7.5-4.6-9.6-9.3C1 8.4 3 5 6.4 5c2 0 3.4 1.1 4.1 2.3h3C14.2 6.1 15.6 5 17.6 5 21 5 23 8.4 21.6 11.7 19.5 16.4 12 21 12 21z" fill={color} /></svg>
);

// ───────── transições ─────────
// círculo de cor que cresce e cobre a tela (o corte acontece embaixo dele) e depois se abre para a cena nova
const Flood: React.FC<{ t: number; at: number; color: string; x?: string; y?: string }> = ({ t, at, color, x = "50%", y = "50%" }) => {
  const grow = k(t, at - 0.3, 0.3, IN_OUT);
  const open = k(t, at, 0.3, IN_OUT);
  if (grow <= 0 || open >= 1) return null;
  return (
    <AbsoluteFill style={{ background: color, clipPath: `circle(${(grow * 120).toFixed(2)}% at ${x} ${y})`, WebkitMaskImage: open > 0 ? `radial-gradient(circle at ${x} ${y}, transparent ${(open * 120).toFixed(1)}%, black ${(open * 120 + 0.5).toFixed(1)}%)` : undefined }} />
  );
};
// faixa que atravessa a tela
const Wipe: React.FC<{ t: number; at: number; color: string; dir: "up" | "down" | "left" | "right" }> = ({ t, at, color, dir }) => {
  const p = interpolate(t, [at - 0.24, at + 0.24], [0, 1], { ...cl, easing: IN_OUT });
  if (p <= 0 || p >= 1) return null;
  const m = (1 - 2 * p) * 125;
  const tr = dir === "up" ? `translateY(${m}%)` : dir === "down" ? `translateY(${-m}%)` : dir === "left" ? `translateX(${m}%)` : `translateX(${-m}%)`;
  return <div style={{ position: "absolute", left: "-15%", top: "-15%", width: "130%", height: "130%", background: color, transform: tr }} />;
};

// cortes (segundos do vídeo)
const C = { s2: v(1.6), s3: v(4.3), s4: v(7.95), s5: v(10.45), s6: v(13.85), s7: v(15.58), s8: v(18.45), s8b: v(19.62), s9: v(20.85), s10: v(22.55), s11: v(26.2), s12: v(29.05) };
const MAIS: [string, number, number, number][] = [
  // [foto, x, y, atraso]
  ["micosan.jpg", 140, 262, 0],
  ["foto-4.jpg", 560, 262, 0.08],
  ["foto-1.jpg", 140, 762, 0.16],
  ["foto-2.jpg", 560, 762, 0.24],
];

export const Binaglow: React.FC = () => {
  const f = useCurrentFrame();
  const t = f / BG_FPS;
  const on = (a: number, b: number) => t >= a && t < b;
  const cam = (a: number, b: number) => interpolate(t, [a, b], [1, 1.05], cl); // câmera lenta nas cenas desenhadas
  const tap = k(t, v(29.6), 0.1) - k(t, v(29.6) + 0.1, 0.25);
  // "e muito mais": a foto 2 cresce do mosaico até virar a tela cheia da cena seguinte
  const grow = k(t, C.s10 - 0.35, 0.5, IN_OUT);
  return (
    <AbsoluteFill style={{ background: BLUSH, fontFamily: SANS }}>
      {/* 1 — "Se amar é se cuidar," */}
      {t < C.s2 ? (
        <>
          <Backdrop src="foto-4.jpg" t={t} a={0} />
          <Card t={t} src="foto-4.jpg" a={-0.25} b={C.s2} w={660} h={880} top={255} />
          <Stack top={1170} gap={22}>
            <Pill t={t} at={0.07} size={60} words={[["Se", 0.07], ["amar", 0.18], ["é", 0.55]]} />
            <Bar t={t} at={0.63} size={128} words={[["se", 0.63], ["cuidar", 0.81]]} />
          </Stack>
        </>
      ) : null}

      {/* 2 — "aqui é o seu lugar, Bina Glow." */}
      {on(C.s2, C.s3) ? (
        <>
          <Stack top={560} gap={0}>
            <Words t={t} size={118} font={SCRIPT} weight={400} color={WINE} ls="0" words={[["aqui", 1.66], ["é", 1.91], ["o", 2.0], ["seu", 2.09], ["lugar", 2.37]]} />
          </Stack>
          <div style={{ position: "absolute", left: 200, top: 770, transform: `scale(${cam(C.s2, C.s3)})` }}>
            <Logo t={t} at={v(3.17)} d={680} />
          </div>
        </>
      ) : null}

      {/* 3 — "Sua beleza merece aquele cuidado especial todos os dias." */}
      {on(C.s3, C.s4) ? (
        <>
          <Backdrop src="creme.jpg" t={t} a={C.s3} />
          <Card t={t} src="creme.jpg" a={C.s3} b={C.s4} w={740} h={735} top={260} />
          <Stack top={1035} gap={14}>
            <Words t={t} size={104} font={SCRIPT} weight={400} color={WINE} ls="0" words={[["Sua", 4.48], ["beleza", 4.55], ["merece", 4.67]]} />
            <Bar t={t} at={5.64} size={100} words={[["cuidado", 5.64], ["especial", 6.21]]} />
            <div style={{ marginTop: 10 }}>
              <Pill t={t} at={6.86} size={54} words={[["todos", 6.86], ["os", 7.26], ["dias", 7.68]]} />
            </div>
          </Stack>
        </>
      ) : null}

      {/* 4 — "Aqui você encontra perfumes íntimos," (lettering em cima: embaixo fica o rótulo do frasco) */}
      {on(C.s4, C.s5) ? (
        <>
          <Backdrop src="foto-1.jpg" t={t} a={C.s4} />
          <Card t={t} src="foto-1.jpg" a={C.s4} b={C.s5} w={660} h={880} top={575} />
          <Stack top={262} gap={20}>
            <Pill t={t} at={8.04} size={54} words={[["Aqui", 8.04], ["você", 8.34], ["encontra", 8.64]]} />
            <Bar t={t} at={9.25} size={104} words={[["Perfumes", 9.25], ["íntimos", 9.92]]} />
          </Stack>
        </>
      ) : null}

      {/* 5 — "body splash feminino e masculino," (foto inteira, sem cortar o frasco) */}
      {on(C.s5, C.s6) ? (
        <>
          <Backdrop src="foto-7.jpg" t={t} a={C.s5} />
          <Card t={t} src="foto-7.jpg" a={C.s5} b={C.s6} w={820} h={897} top={258} from="scale" />
          <Stack top={1190} gap={22}>
            <Bar t={t} at={10.58} size={112} words={[["Body", 10.58], ["Splash", 11.27]]} />
            <Pill t={t} at={11.53} size={56} words={[["feminino", 11.53], ["e", 12.32], ["masculino", 12.5]]} />
          </Stack>
        </>
      ) : null}

      {/* 6 — "kits e óleos capilares," */}
      {on(C.s6, C.s7) ? (
        <>
          <Backdrop src="capilar.jpg" t={t} a={C.s6} />
          <Card t={t} src="capilar.jpg" a={C.s6} b={C.s7} w={820} h={555} top={430} from="scale" />
          <Stack top={1050} gap={4}>
            <Bar t={t} at={14.02} size={108} words={[["Kits", 14.02], ["e", 14.05], ["óleos", 14.1]]} />
            <Words t={t} size={130} font={SCRIPT} weight={400} color={WINE} ls="0" words={[["capilares", 14.41]]} />
          </Stack>
        </>
      ) : null}

      {/* 7 — "máscaras faciais e skincare," */}
      {on(C.s7, C.s8) ? (
        <>
          <Backdrop src="mascara.jpg" t={t} a={C.s7} />
          <Card t={t} src="mascara.jpg" a={C.s7} b={C.s8} w={480} h={908} top={262} />
          <Stack top={1200} gap={22}>
            <Bar t={t} at={15.67} size={104} words={[["Máscaras", 15.67], ["faciais", 16.29]]} />
            <Pill t={t} at={17.0} size={56} words={[["e", 17.0], ["skincare", 17.24]]} />
          </Stack>
        </>
      ) : null}

      {/* 8 — "cremes clareadores, escovas de cabelo" (sem foto: cena desenhada no pink) */}
      {on(C.s8, C.s9) ? (
        <AbsoluteFill style={{ background: PINK }}>
          <AbsoluteFill style={{ background: `radial-gradient(circle at 50% 42%, ${ROSE}66 0%, transparent 55%)` }} />
          {t < C.s8b ? (
            <>
              <div style={{ position: "absolute", left: 360, top: 880, transform: `scale(${cam(C.s8, C.s8b)})` }}>
                <Icon t={t} at={v(18.6)} kind="jar" size={360} />
              </div>
              <Stack top={420} gap={0}>
                <Words t={t} size={160} font={SERIF} weight={700} italic color={WHITE} words={[["Cremes", 18.66]]} />
                <Words t={t} size={160} font={SERIF} weight={700} italic color={WHITE} words={[["clareadores", 18.73]]} />
              </Stack>
            </>
          ) : (
            <>
              <div style={{ position: "absolute", left: 360, top: 880, transform: `scale(${cam(C.s8b, C.s9)})` }}>
                <Icon t={t} at={v(19.7)} kind="brush" size={360} />
              </div>
              <Stack top={420} gap={0}>
                <Words t={t} size={160} font={SERIF} weight={700} italic color={WHITE} words={[["Escovas", 19.7]]} />
                <Words t={t} size={160} font={SERIF} weight={700} italic color={WHITE} words={[["de", 20.31], ["cabelo", 20.56]]} />
              </Stack>
            </>
          )}
        </AbsoluteFill>
      ) : null}

      {/* 9 — "e muito mais." mosaico; a foto 2 cresce e vira a cena 10 */}
      {on(C.s9, C.s10 + 0.2) ? (
        <>
          {MAIS.map(([src, x, y, d], i) => {
            const e = k(t, C.s9 + d, 0.5, BACK);
            const last = i === 3;
            const out = last ? 0 : k(t, C.s10 - 0.35, 0.3);
            const L = last ? interpolate(grow, [0, 1], [x, 210]) : x;
            const T = last ? interpolate(grow, [0, 1], [y, 575]) : y;
            const Wd = last ? interpolate(grow, [0, 1], [380, 660]) : 380;
            const Hd = last ? interpolate(grow, [0, 1], [470, 880]) : 470;
            return (
              <div key={src} style={{ position: "absolute", left: L, top: T, width: Wd, height: Hd, borderRadius: last ? 30 + 6 * grow : 30, overflow: "hidden", boxShadow: "0 22px 50px rgba(91,22,49,0.22)", transform: `scale(${(0.6 + 0.4 * e) * (1 - out * 0.2)})`, opacity: k(t, C.s9 + d, 0.12) * (1 - out), zIndex: last ? 2 : 1 }}>
                <Img src={staticFile(`binaglow/${src}`)} style={{ width: "100%", height: "100%", objectFit: "cover", objectPosition: src === "foto-2.jpg" ? "30% 50%" : "50% 50%" }} />
              </div>
            );
          })}
          <div style={{ opacity: 1 - k(t, C.s10 - 0.4, 0.2) }}>
            <Stack top={1250} gap={0}>
              <Words t={t} size={140} font={SCRIPT} weight={400} color={WINE} ls="0" words={[["e", 20.95], ["muito", 21.03], ["mais!", 21.44]]} />
            </Stack>
          </div>
        </>
      ) : null}

      {/* 10 — "Tudo para a sua rotina de autocuidado em um só lugar." */}
      {on(C.s10 + 0.2, C.s11) ? (
        <>
          <Backdrop src="foto-2.jpg" t={t} a={C.s10} />
          <div style={{ position: "absolute", left: 210, top: 575, width: 660, height: 880, borderRadius: 36, overflow: "hidden", boxShadow: "0 30px 70px rgba(91,22,49,0.28)" }}>
            <Img src={staticFile("binaglow/foto-2.jpg")} style={{ width: "100%", height: "100%", objectFit: "cover", objectPosition: "30% 50%", transform: `scale(${interpolate(t, [C.s10 + 0.2, C.s11], [1, 1.07], cl)})` }} />
          </div>
          <Stack top={262} gap={18}>
            <Pill t={t} at={22.76} size={52} words={[["Tudo", 22.76], ["para", 22.76], ["a", 22.83], ["sua", 22.9], ["rotina", 23.16], ["de", 23.7]]} />
            <Bar t={t} at={23.85} size={110} words={[["autocuidado", 23.85]]} />
            <Pill t={t} at={24.8} size={52} words={[["em", 24.8], ["um", 25.03], ["só", 25.14], ["lugar", 25.3]]} />
          </Stack>
        </>
      ) : null}

      {/* 11 — "E a gente entrega em todo o ABC." */}
      {on(C.s11, C.s12) ? (
        <>
          <div style={{ position: "absolute", left: 0, top: 0, width: 1080, height: 1920, transform: `scale(${cam(C.s11, C.s12)})` }}>
            <svg width={1080} height={1920} style={{ position: "absolute", inset: 0 }}>
              <path d="M150 1000 C 300 840, 420 980, 540 800" fill="none" stroke={ROSE} strokeWidth="10" strokeLinecap="round" strokeDasharray="2 26" pathLength={1000} strokeDashoffset={0} opacity={k(t, v(26.45), 0.2)} style={{ clipPath: `inset(0 ${100 - 100 * k(t, v(26.45), 0.9, IN_OUT)}% 0 0)` }} />
              <path d="M930 1000 C 780 840, 660 980, 540 800" fill="none" stroke={ROSE} strokeWidth="10" strokeLinecap="round" strokeDasharray="2 26" pathLength={1000} opacity={k(t, v(26.6), 0.2)} style={{ clipPath: `inset(0 0 0 ${100 - 100 * k(t, v(26.6), 0.9, IN_OUT)}%)` }} />
            </svg>
            <div style={{ position: "absolute", left: 125, top: 975, width: 50, height: 50, borderRadius: "50%", background: PINK, transform: `scale(${k(t, v(26.4), 0.4, BACK)})` }} />
            <div style={{ position: "absolute", left: 905, top: 975, width: 50, height: 50, borderRadius: "50%", background: PINK, transform: `scale(${k(t, v(26.55), 0.4, BACK)})` }} />
            <div style={{ position: "absolute", left: 415, top: 500, width: 250, height: 250, display: "flex", justifyContent: "center" }}>
              <Icon t={t} at={v(26.45)} kind="pin" size={250} color={PINK} />
            </div>
          </div>
          <Stack top={1140} gap={16}>
            <Words t={t} size={70} weight={500} color={WINE} words={[["A", 26.38], ["gente", 26.45], ["entrega", 26.48], ["em", 27.12]]} />
            <Bar t={t} at={27.32} size={140} words={[["todo", 27.32], ["o", 27.68], ["ABC", 28.03]]} />
          </Stack>
        </>
      ) : null}

      {/* 12 — "Chama no WhatsApp e garanta os seus. Você merece esse carinho." */}
      {t >= C.s12 ? (
        <>
          {/* fundo com uma luz rosa suave que passeia devagar: a tela final nunca fica parada */}
          <AbsoluteFill style={{ background: `radial-gradient(circle at ${interpolate(t, [C.s12, BG_FRAMES / BG_FPS], [25, 75], cl)}% ${interpolate(t, [C.s12, BG_FRAMES / BG_FPS], [30, 62], cl)}%, ${ROSE}AA 0%, transparent 48%)` }} />
          <div style={{ position: "absolute", left: 300, top: 285, transform: `scale(${interpolate(t, [C.s12, BG_FRAMES / BG_FPS], [1, 1.08], cl)})` }}>
            <Logo t={t} at={C.s12 + 0.15} d={480} />
          </div>
          <Stack top={815} gap={26}>
            <Words t={t} size={62} weight={500} color={WINE} words={[["Chama", 29.23], ["no", 29.46], ["WhatsApp", 29.58]]} />
            <div style={{ display: "flex", alignItems: "center", gap: 22, padding: "24px 50px 24px 26px", borderRadius: 999, background: PINK, boxShadow: "0 18px 40px rgba(230,62,126,0.35)", transform: `scale(${k(t, v(29.4), 0.45, BACK) * (1 - tap * 0.06)})`, opacity: k(t, v(29.4), 0.1) }}>
              <div style={{ width: 92, height: 92, borderRadius: "50%", background: WHITE, display: "flex", alignItems: "center", justifyContent: "center" }}>
                <svg width="56" height="56" viewBox="0 0 24 24" fill={PINK}>
                  <path d="M12 2a10 10 0 0 0-8.6 15.1L2 22l5-1.3A10 10 0 1 0 12 2zm0 18.2a8.2 8.2 0 0 1-4.2-1.2l-.3-.2-3 .8.8-2.9-.2-.3A8.2 8.2 0 1 1 12 20.2zm4.5-6.1c-.2-.1-1.5-.7-1.7-.8-.2-.1-.4-.1-.6.1l-.8 1c-.1.2-.3.2-.5.1a6.7 6.7 0 0 1-3.3-2.9c-.3-.4.3-.4.8-1.4.1-.2 0-.3 0-.4l-.8-1.8c-.2-.5-.4-.4-.6-.4h-.5a1 1 0 0 0-.7.3 3 3 0 0 0-.9 2.2 5.2 5.2 0 0 0 1.1 2.8 11.9 11.9 0 0 0 4.6 4c1.7.7 2.3.8 3.2.7.5-.1 1.5-.6 1.7-1.2.2-.6.2-1.1.2-1.2-.1-.1-.3-.2-.5-.3z" />
                </svg>
              </div>
              <span style={{ fontFamily: SANS, fontWeight: 700, fontSize: 66, color: WHITE, letterSpacing: "-0.01em", fontVariantNumeric: "tabular-nums" }}>(00) 00000-0000</span>
            </div>
            <Words t={t} size={50} weight={500} color={PINK} words={[["e", 30.1], ["garanta", 30.13], ["os", 30.67], ["seus", 30.81]]} />
          </Stack>
          <Stack top={1175} gap={0}>
            <Words t={t} size={94} font={SCRIPT} weight={400} color={WINE} ls="0" words={[["Você", 31.7], ["merece", 31.7]]} />
            <div style={{ display: "flex", alignItems: "center", gap: 18, marginTop: -24 }}>
              <Words t={t} size={94} font={SCRIPT} weight={400} color={WINE} ls="0" words={[["esse", 31.91], ["carinho", 32.21]]} />
              <div style={{ transform: `scale(${k(t, v(32.9), 0.45, BACK)})` }}>
                <Heart size={54} />
              </div>
            </div>
          </Stack>
        </>
      ) : null}

      <Flood t={t} at={C.s2} color={PINK} x="50%" y="78%" />
      <Wipe t={t} at={C.s3} color={ROSE} dir="up" />
      <Wipe t={t} at={C.s4} color={WINE} dir="left" />
      <Wipe t={t} at={C.s5} color={PINK} dir="right" />
      <Flood t={t} at={C.s6} color={BLUSH} x="50%" y="50%" />
      <Wipe t={t} at={C.s7} color={ROSE} dir="down" />
      <Flood t={t} at={C.s8} color={PINK} x="50%" y="80%" />
      <Wipe t={t} at={C.s9} color={BLUSH} dir="up" />
      <Flood t={t} at={C.s11} color={ROSE} x="30%" y="20%" />
      <Wipe t={t} at={C.s12} color={PINK} dir="up" />
    </AbsoluteFill>
  );
};

